            for c in content:
                if isinstance(c, dict):
                    parts.append(walk(c))
                else:
                    parts.append({"type": "text", "text": str(c)})
        elif content:
            parts.append({"type": "text", "text": json.dumps(content, ensure_ascii=False)})
